protected void cleanup()
{
    SalesParmCleanUp                            salesParmCleanUp;
    SalesParmLine                               salesParmLine;
    int64                                       recCount;
    boolean                                     shouldContinue = true;

    while select crosscompany salesParmLine
        group by DataAreaId
    {
        changeCompany(salesParmLine.dataAreaId)
        {
            if (cleanupTaskSettings.isCleanupAllowedForCompany(salesParmLine.dataAreaId))
            {
                recCount = this.countRecords(tableNum(SalesParmLine));

                salesParmCleanUp = SalesParmCleanUp::construct();
                salesParmCleanUp.DEVCleanUp_cleanUpMode(SalesPurchParmCleanUpMode::All);
                salesParmCleanUp.DEVCleanUp_setDaysAgo(true);
                salesParmCleanUp.DEVCleanUp_daysAgo(cleanupTaskSettings.cleanupDaysForCompany(salesParmLine.dataAreaId));
                salesParmCleanUp.runOperation();

                shouldContinue = this.addDeletedRecords(recCount - this.countRecords(tableNum(SalesParmLine)));
            }
        }

        if (!shouldContinue)
        {
            break;
        }
    }
}

public DEV_CleanUpTaskName getTaskName()
{
    ;
    return 'SalesParmLine table cleanup(Standard)';
}

public void estimate()
{        
    SalesParmLine   salesParmLineGroup;

    info("Company, RecCount");

    while select crosscompany salesParmLineGroup
        group by DataAreaId
    {
        changeCompany(salesParmLineGroup.dataAreaId)
        {
            if (cleanupTaskSettings.isCleanupAllowedForCompany(salesParmLineGroup.dataAreaId))
            {
                utcdatetime     cleanUpDateTime = cleanupTaskSettings.cleanupDateTimeForCompany(salesParmLineGroup.dataAreaId);
                int64           recordCount;
                SalesParmLine   salesParmLine;
                salesParmTable  salesParmTable;

                select count(RecId) from salesParmLine
                    notexists join salesParmTable
                        where   salesParmTable.ParmId == salesParmLine.ParmId
                                && salesParmTable.TableRefId == salesParmLine.TableRefId;

                recordCount = salesParmLine.RecId;

                salesParmLine   = null;
                salesParmTable  = null;

                select count(RecId) from salesParmLine
                    join TableId from salesParmTable
                        where   salesParmTable.ParmId == salesParmLine.ParmId
                                && salesParmTable.TableRefId == salesParmLine.TableRefId
                                && salesParmTable.createdDateTime <= cleanUpDateTime;

                recordCount += salesParmLine.RecId;

                info(strFmt("%1, %2", salesParmLineGroup.dataAreaId, recordCount));
            }
            else if (cleanupTaskSettings.PerCompanySetup)
            {
                warning(strFmt("%1, settings were not found!", salesParmLineGroup.dataAreaId));
            }
        }
    }
}
